/* @lc app=leetcode id=1901 lang=kotlin */ class Solution { fun findPeakGrid(mat: Array<IntArray>): IntArray = generateSequence(intArrayOf(0, mat.size - 1)) { v -> (v[0] + (v[1] - v[0]) / 2).let { m -> mat[m].indices.maxByOrNull { mat[m][it] }!!.let { c -> if ((m == 0 || mat[m][c] > mat[m - 1][c]) && (m == mat.size - 1 || mat[m][c] > mat[m + 1][c])) intArrayOf(-1, m, c) else if (m > 0 && mat[m - 1][c] > mat[m][c]) intArrayOf(v[0], m - 1) else intArrayOf(m + 1, v[1]) } } }.first { it[0] == -1 }.let { intArrayOf(it[1], it[2]) } }